    L.left = (r.left + ox + bl) + "px";
    L.top = (r.top + oy + bt) + "px";
    L.width = Math.max(0, r.width - bl - br) + "px";
    L.height = Math.max(0, r.height - bt - bb) + "px";
    L.borderRadius = cs.borderRadius;
